  <div style="border:1px solid rgb(var(--c-primary-rgb)/.3);background:rgb(var(--c-primary-rgb)/.06);border-radius:.75rem;padding:.75rem" aria-live="polite"><div class="text-xs muted">Selling price (calculated, read-only)</div>
