<script>(()=>{const PCT=<?= json_encode((float)($discountPct ?? company_discount())) ?>,SKUS=<?= json_encode((object)($skuPreview ?? [])) ?>;
  const o=document.getElementById('original_price'),amt=document.getElementById('sp-amount'),cat=document.getElementById('category_id'),sku=document.getElementById('sku'),hint=document.getElementById('sku-hint');
  const fmt=n=>'₹'+n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
  const calc=()=>{const m=parseFloat(o.value);if(!(m>0)){amt.textContent='₹0.00';return}const d=Math.round(m*PCT)/100;amt.textContent=fmt(Math.round((m-d)*100)/100)};   // same rule as the server: MRP − round(MRP × % ÷ 100, 2)
  o.addEventListener('input',calc);calc();
  if(cat&&hint&&!<?= $id ? 'true' : 'false' ?>){const sh=()=>{const n=SKUS[cat.value];hint.textContent=n?'Next SKU for this category: '+n+' (confirmed when you save).':'Generated automatically from the category when you save.'};cat.addEventListener('change',sh);sh()}
})()</script>
<script>(()=>{const i=document.getElementById('video'),v=document.getElementById('video-preview');if(!i)return;i.addEventListener('change',()=>{const f=i.files[0];if(!f){v.classList.add('hidden');return}if(f.size>50*1024*1024){alert('Video must be under 50 MB.');i.value='';v.classList.add('hidden');return}v.src=URL.createObjectURL(f);v.classList.remove('hidden')})})()</script>
<script>(()=>{const i=document.getElementById('images');if(!i)return;
  const form=i.form,prev=document.getElementById('img-preview'),warn=document.getElementById('img-warn'),vid=document.getElementById('video');
  const MAX=+i.dataset.maxFile,POST=+i.dataset.postMax,OK=i.dataset.allowed.split(','),LABEL=i.dataset.label,EXT=/\.(png|jpe?g|webp|gif|avif)$/i;
  const mb=n=>(n/1048576).toFixed(n>=1048576?1:2)+' MB';let urls=[],blocked=[];
  const typeOk=f=>OK.includes(f.type)||(f.type===''&&EXT.test(f.name));   // some browsers give no MIME for .avif/.webp: fall back to the extension (the server checks the real content anyway)
  function render(){
    urls.forEach(u=>URL.revokeObjectURL(u));urls=[];prev.innerHTML='';blocked=[];let total=0;
    [...i.files].forEach(f=>{total+=f.size;const ok=typeOk(f),big=f.size>MAX,box=document.createElement('div');box.className='w-28 text-xs';
      const fr=document.createElement('div');fr.className='w-28 h-28 rounded-lg border bg-gray-50 overflow-hidden flex items-center justify-center text-gray-400 text-[11px] text-center p-1'+((!ok||big)?' border-red-400':'');
      if(ok){const im=document.createElement('img'),u=URL.createObjectURL(f);urls.push(u);im.src=u;im.alt='';im.className='w-full h-full object-cover';im.onerror=()=>{fr.textContent='Preview not available'};fr.appendChild(im)}else fr.textContent='Not an image';
      const nm=document.createElement('div');nm.className='mt-1 truncate';nm.title=f.name;nm.textContent=f.name;
      const sz=document.createElement('div');sz.className=big?'text-red-700 font-semibold':'muted';sz.textContent=mb(f.size)+(big?' – too big':'');
      box.append(fr,nm,sz);prev.appendChild(box);
      if(!ok)blocked.push(f.name+': this is not an allowed image type ('+LABEL+').');
      if(big)blocked.push(f.name+' is '+mb(f.size)+' – the limit is '+mb(MAX)+' per image.');});
    const vs=vid&&vid.files[0]?vid.files[0].size:0;
    if(POST&&total+vs>POST*0.95)blocked.push('The selected files total '+mb(total+vs)+', but the server accepts about '+mb(POST)+' per save. Choose fewer or smaller files.');
    warn.innerHTML='';blocked.forEach(m=>{const p=document.createElement('p');p.textContent=m;warn.appendChild(p)});warn.classList.toggle('hidden',!blocked.length);
  }
  i.addEventListener('change',render);if(vid)vid.addEventListener('change',render);
  form.addEventListener('submit',e=>{render();if(blocked.length){e.preventDefault();e.stopImmediatePropagation();warn.scrollIntoView({block:'center',behavior:'smooth'})}});   // stop BEFORE sending: the form is never lost
})()</script>
